-- starter-04 · Build the Bridge
UPDATE levels SET title = 'Build the Bridge', brief_description = 'The stream washed the footbridge away. Push all three bridge blocks into the construction zone, then cross to the far bank.',
       description = 'The stream washed the footbridge away. Push all three bridge blocks into the construction zone, then cross to the far bank. Environment: Bridge Site — A meadow lane beside the washed-out stream, with three bridge blocks and the construction site.',
       difficulty = 'EASY', environment_id = 'starter-meadow-lanes', estimated_minutes = 8,
       xp_reward = 110, par_blocks = 16, par_seconds = 52,
       allowed_blocks = ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed']::text[], intro_steps = ARRAY['Drive up beside a bridge block', 'Turn towards the construction zone and push it in', 'Back up, do the next block, then drive to the far bank']::text[],
       map_definition = '{"id":"level-starter-04","name":"Build the Bridge","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":0.9,"heading":0},"finish":{"shape":"rect","center":{"x":1.7,"z":0.9},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"site","type":"zone","kind":"construction","area":{"shape":"rect","center":{"x":-0.4,"z":-0.55},"size":{"x":2.6,"z":0.8},"rotation":0},"label":"BRIDGE SITE"},{"id":"block-1","type":"box","position":{"x":-1.2,"z":0.45},"size":{"x":0.12,"y":0.12,"z":0.12},"rotation":0,"dynamic":true},{"id":"block-2","type":"box","position":{"x":-0.4,"z":0.45},"size":{"x":0.12,"y":0.12,"z":0.12},"rotation":0,"dynamic":true},{"id":"block-3","type":"box","position":{"x":0.4,"z":0.45},"size":{"x":0.12,"y":0.12,"z":0.12},"rotation":0,"dynamic":true},{"id":"fence-south","type":"wall","from":{"x":-2.9,"z":1.35},"to":{"x":2.3,"z":1.35},"height":0.12,"thickness":0.06},{"id":"fence-west","type":"wall","from":{"x":-2.9,"z":-1.15},"to":{"x":-2.9,"z":1.35},"height":0.12,"thickness":0.06},{"id":"fence-north","type":"wall","from":{"x":-2.9,"z":-1.15},"to":{"x":2.3,"z":-1.15},"height":0.12,"thickness":0.06},{"id":"fence-east","type":"wall","from":{"x":2.3,"z":-1.15},"to":{"x":2.3,"z":1.35},"height":0.12,"thickness":0.06}]}'::jsonb, scene_config = '{"path":[{"x":-2.7,"z":0.9},{"x":2,"z":0.9}],"pathWidth":0.7,"water":[{"points":[{"x":-3.8,"z":-1.75},{"x":0,"z":-1.6},{"x":3.8,"z":-1.75}],"width":0.7,"depth":0.3}]}'::jsonb, mission_settings = '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Build the Bridge","missionDescription":"Push the three bridge blocks into the construction zone and reach the far bank.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":52,"maxPoints":200},"efficiencyBonus":{"parBlocks":16,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"Power and supplies are flowing again, but the storm washed the footbridge over the meadow stream away. The builders left three bridge blocks beside the lane — your robot has to push them onto the bridge site.","task":"Push all three bridge blocks into the construction zone, then drive to the far bank.","objectives":{"primary":"Push 3 blocks into the construction zone and reach the far bank","secondary":"Finish within 52 seconds","optional":"Use 16 blocks or fewer"},"concepts":["Pushing objects","Repeated steps","Sequence","Backing up"],"python":["robot.move_forward(cm)","robot.move_backward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)"],"predict":"How far must the robot push so a block ends up inside the zone? Which moves are the same for every block?","pseudocode":["drive beside block 1","turn towards the zone, push, back up, turn back","drive beside block 2 — same moves","drive beside block 3 — same moves","drive to the far bank"],"minutes":8,"tier":"medium","mechanics":["push"]}}'::jsonb
 WHERE slug = 'starter-04';
DELETE FROM student_objective_progress WHERE objective_id IN (SELECT id FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04'));
DELETE FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04');
DELETE FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04');
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'build', 'Push 3 blocks into the construction zone', 'CUSTOM', NULL, '{"tracked":true,"kind":"pushToZone","zoneId":"site","count":3}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'goal', 'Reach the far bank', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
UPDATE level_hints SET title = 'Hint 1', content = 'The robot can push a block simply by driving into it. Every block needs the same moves: drive beside it, turn, push, back up, turn back.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 1;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 1', 'The robot can push a block simply by driving into it. Every block needs the same moves: drive beside it, turn, push, back up, turn back.', 0, 1 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 1);
UPDATE level_hints SET title = 'Hint 2', content = 'drive to block 1 → turn left → push forward → drive backward → turn right → drive to block 2 → … → drive to the far bank.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 2;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 2', 'drive to block 1 → turn left → push forward → drive backward → turn right → drive to block 2 → … → drive to the far bank.', 0, 2 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 2);
UPDATE level_hints SET title = 'Hint 3', content = 'move forward 120 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward ? → … The blocks are 80 cm apart.', cost = 0 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 3;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 3', 'move forward 120 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward ? → … The blocks are 80 cm apart.', 0, 3 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 3);
UPDATE level_hints SET title = 'Hint 4', content = 'move forward 120 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 80 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 80 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 130.', cost = 10 WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 4;
INSERT INTO level_hints (level_id, title, content, cost, sort_order) SELECT (SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 4', 'move forward 120 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 80 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 80 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 130.', 10, 4 WHERE NOT EXISTS (SELECT 1 FROM level_hints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-04') AND sort_order = 4);

-- starter-05 · Traffic Crossing
UPDATE levels SET title = 'Traffic Crossing', brief_description = 'The traffic lights work again. Cross both zebra crossings on the way to the depot — never on red. Stop at the line and wait for green.',
       description = 'The traffic lights work again. Cross both zebra crossings on the way to the depot — never on red. Stop at the line and wait for green. Environment: Traffic Crossing — Hedge-lined roads with two zebra crossings and their traffic lights on the way to the depot.',
       difficulty = 'EASY', environment_id = 'starter-beacon-field', estimated_minutes = 8,
       xp_reward = 110, par_blocks = 7, par_seconds = 32,
       allowed_blocks = ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait']::text[], intro_steps = ARRAY['Watch the lights: when does each one turn green?', 'Stop before the crossing and wait', 'Cross on green — the robot must never enter on red']::text[],
       map_definition = '{"id":"level-starter-05","name":"Traffic Crossing","schemaVersion":1,"size":{"x":6,"z":4.6},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":0.8,"heading":0},"finish":{"shape":"rect","center":{"x":0.6,"z":-1.4},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"light-a","type":"trafficLight","position":{"x":-1.2,"z":0.25},"facing":3.141592653589793,"crossing":{"shape":"rect","center":{"x":-1,"z":0.8},"size":{"x":0.3,"z":0.84},"rotation":0},"signal":{"shape":"rect","center":{"x":-1.23,"z":0.8},"size":{"x":0.12,"z":0.3},"rotation":0},"cycle":{"red":8,"green":6,"yellow":1},"offset":0},{"id":"light-b","type":"trafficLight","position":{"x":1.15,"z":0},"facing":-1.5707963267948966,"crossing":{"shape":"rect","center":{"x":0.6,"z":-0.2},"size":{"x":0.84,"z":0.3},"rotation":0},"signal":{"shape":"rect","center":{"x":0.6,"z":0.22},"size":{"x":0.3,"z":0.12},"rotation":0},"cycle":{"red":7,"green":6,"yellow":1},"offset":11},{"id":"hedge-a1","type":"wall","from":{"x":-2.7,"z":1.22},"to":{"x":1.02,"z":1.22},"height":0.12,"thickness":0.06},{"id":"hedge-b1","type":"wall","from":{"x":-2.7,"z":0.38},"to":{"x":0.18,"z":0.38},"height":0.12,"thickness":0.06},{"id":"hedge-a2","type":"wall","from":{"x":1.02,"z":1.22},"to":{"x":1.02,"z":-1.9},"height":0.12,"thickness":0.06},{"id":"hedge-b2","type":"wall","from":{"x":0.18,"z":0.38},"to":{"x":0.18,"z":-1.9},"height":0.12,"thickness":0.06},{"id":"hedge-cap1","type":"wall","from":{"x":1.02,"z":-1.9},"to":{"x":0.18,"z":-1.9},"height":0.12,"thickness":0.06}]}'::jsonb, scene_config = '{"path":[{"x":-2.7,"z":0.8},{"x":0.6,"z":0.8},{"x":0.6,"z":-1.7}],"pathWidth":0.84}'::jsonb, mission_settings = '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Traffic Crossing","missionDescription":"Cross both crossings on green and reach the depot.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":32,"maxPoints":200},"efficiencyBonus":{"parBlocks":7,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The island’s traffic lights are working again — and the island’s robots have to obey them like everyone else. The depot is on the other side of two zebra crossings.","task":"Drive to the depot without ever entering a crossing on red.","objectives":{"primary":"Reach the depot without crossing on red","secondary":"Finish within 32 seconds","optional":"Use 7 blocks or fewer"},"concepts":["Timing","Wait","Reading a timetable","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.wait(seconds)"],"predict":"The robot drives 25 cm every second. When will it reach the first crossing — and what colour will the light be then?","pseudocode":["drive to the first stop line","wait until light A is green","drive to the corner and turn","drive to the second stop line","wait until light B is green","drive to the depot"],"minutes":8,"tier":"medium","mechanics":["traffic"]}}'::jsonb
 WHERE slug = 'starter-05';
DELETE FROM student_objective_progress WHERE objective_id IN (SELECT id FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-05'));
DELETE FROM level_objectives WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-05');
DELETE FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-05');
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'goal', 'Reach the depot', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
