-- starter-06 · Rescue Route
UPDATE levels SET title = 'Rescue Route', brief_description = 'Three hikers are stranded in the woods. Reach them strictly in order — 1, 2, 3 — then return to the ranger station. Hiker 2 is on the short way to hiker 1.',
       description = 'Three hikers are stranded in the woods. Reach them strictly in order — 1, 2, 3 — then return to the ranger station. Hiker 2 is on the short way to hiker 1. Environment: Rescue Woods — A boulder-strewn forest clearing where three hikers wait, and the ranger station.',
