UPDATE level_hints SET title = 'Hint 3', content = 'k = 1
for _ in range(mission.count):
    robot.move_forward(k * 70)
    robot.turn_left(90)
    robot.move_forward(30)
    robot.pick_up()
    robot.move_backward(30)
    robot.turn_right(90)
